package br.com.admeclesial.application.financeiro; import br.com.admeclesial.domain.financeiro.*; import br.com.admeclesial.infrastructure.persistence.financeiro.CategoriaFinanceiraRepository; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.util.*; @Service public class CategoriaFinanceiraApplicationService { final CategoriaFinanceiraRepository r; public CategoriaFinanceiraApplicationService(CategoriaFinanceiraRepository r){this.r=r;} @Transactional public CategoriaFinanceira criar(CategoriaFinanceiraRequest x){var e=new CategoriaFinanceira();e.setCodigo(x.codigo().trim());e.setNome(x.nome().trim());e.setTipo(x.tipo());e.setAtivo(x.ativo()==null||x.ativo());return r.save(e);} @Transactional(readOnly=true) public List<CategoriaFinanceira> listar(){return r.findAllByOrderByNomeAsc();}}